// src/screens/WelcomeScreen.js

import React, { useEffect, useState } from 'react';
import {
  View,
  Text,
  TouchableOpacity,
  StyleSheet,
  Animated,
  Dimensions,
  ImageBackground,
  StatusBar,
} from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { useApp } from '../context';

const { width, height } = Dimensions.get('window');

const WelcomeScreen = ({ navigation }) => {
  const appContext = useApp();
  const [fadeAnim] = useState(new Animated.Value(0));
  const [slideAnim] = useState(new Animated.Value(50));
  const [scaleAnim] = useState(new Animated.Value(0.8));

  useEffect(() => {
    // Orchestrated entrance animation
    Animated.stagger(300, [
      Animated.parallel([
        Animated.timing(fadeAnim, {
          toValue: 1,
          duration: 1000,
          useNativeDriver: true,
        }),
        Animated.timing(slideAnim, {
          toValue: 0,
          duration: 800,
          useNativeDriver: true,
        }),
      ]),
      Animated.spring(scaleAnim, {
        toValue: 1,
        tension: 100,
        friction: 8,
        useNativeDriver: true,
      }),
    ]).start();
  }, []);

  const handleGetStarted = () => {
    // Navigate directly to the survey screen
    navigation.navigate('Onboarding', { screen: 'Survey' });
  };

  const handleSkipForNow = () => {
    // Skip onboarding but mark as completed and navigate properly
    
    if (appContext.updateUserStats) {
      // Mark survey as completed even when skipped
      appContext.updateUserStats({
        ...appContext.userStats,
        surveyCompleted: true,
        lastSurveyCompletion: new Date().toISOString(),
        surveySkipped: true, // Add a flag to indicate it was skipped
      }).then(() => {
        // Prefer hard navigation to main tabs so the dashboard is visible immediately
        setTimeout(() => {
          try {
            navigation.reset({ index: 0, routes: [{ name: 'MainTabs' }] });
          } catch (e) {
            // Fallback to navigate if reset fails
            navigation.navigate('MainTabs');
          }
        }, 150);
      }).catch((error) => {
        console.error('Error updating user stats for skip:', error);
        // Still try to navigate to main app even if update fails
        navigation.reset({ index: 0, routes: [{ name: 'MainTabs' }] });
      });
    } else {
      // Fallback navigation to main tabs
      navigation.reset({ index: 0, routes: [{ name: 'MainTabs' }] });
    }
  };

  return (
    <View style={styles.container}>
      <StatusBar barStyle="light-content" backgroundColor="#007AFF" />
      {/* Top-right actions (settings/demo toggle) */}
      <View style={styles.topRightActions}>
        <TouchableOpacity
          onPress={async () => {
            try {
              await appContext?.setDemoMode && appContext.setDemoMode(!appContext?.isDemo);
            } catch (e) {
              console.warn('Failed to toggle demo mode', e);
            }
          }}
          activeOpacity={0.8}
          style={[styles.gearButton, appContext?.isDemo ? styles.gearOn : styles.gearOff]}
        >
          <Ionicons name="settings-outline" size={16} color={appContext?.isDemo ? '#fff' : '#0f172a'} />
        </TouchableOpacity>
      </View>
      
      {/* Hero Section */}
      <View style={styles.heroSection}>
        <Animated.View 
          style={[
            styles.heroContent,
            {
              opacity: fadeAnim,
              transform: [
                { translateY: slideAnim },
                { scale: scaleAnim },
              ],
            },
          ]}
        >
          {/* Gymmy Logo/Character */}
          <View style={styles.logoContainer}>
            <View style={styles.logoCircle}>
              <Text style={styles.logoEmoji}>💪</Text>
            </View>
          </View>
          
          <Text style={styles.welcomeTitle}>Meet Gymmy!</Text>
          <Text style={styles.welcomeSubtitle}>
            Your personal fitness companion who grows stronger with you
          </Text>
        </Animated.View>
      </View>

      {/* Features Section */}
      <Animated.View 
        style={[
          styles.featuresSection,
          {
            opacity: fadeAnim,
            transform: [{ translateY: slideAnim }],
          },
        ]}
      >
        <Text style={styles.featuresTitle}>What makes Gymmy special?</Text>
        
        <View style={styles.featuresList}>
          <View style={styles.featureItem}>
            <View style={styles.featureIcon}>
              <Ionicons name="person" size={24} color="#007AFF" />
            </View>
            <View style={styles.featureContent}>
              <Text style={styles.featureTitle}>Personalized for YOU</Text>
              <Text style={styles.featureDescription}>
                Adapts to your fitness values and goals
              </Text>
            </View>
          </View>

          <View style={styles.featureItem}>
            <View style={styles.featureIcon}>
              <Ionicons name="trending-up" size={24} color="#28a745" />
            </View>
            <View style={styles.featureContent}>
              <Text style={styles.featureTitle}>1% Better Every Day</Text>
              <Text style={styles.featureDescription}>
                Small improvements that create big results
              </Text>
            </View>
          </View>

          <View style={styles.featureItem}>
            <View style={styles.featureIcon}>
              <Ionicons name="heart" size={24} color="#dc3545" />
            </View>
            <View style={styles.featureContent}>
              <Text style={styles.featureTitle}>Celebrates Your Progress</Text>
              <Text style={styles.featureDescription}>
                Every step forward is worth celebrating
              </Text>
            </View>
          </View>

          <View style={styles.featureItem}>
            <View style={styles.featureIcon}>
              <Ionicons name="people" size={24} color="#6f42c1" />
            </View>
            <View style={styles.featureContent}>
              <Text style={styles.featureTitle}>Grows With You</Text>
              <Text style={styles.featureDescription}>
                Evolves and adapts as your fitness journey progresses
              </Text>
            </View>
          </View>
        </View>
      </Animated.View>

      {/* Call to Action */}
      <Animated.View 
        style={[
          styles.ctaSection,
          {
            opacity: fadeAnim,
            transform: [{ translateY: slideAnim }],
          },
        ]}
      >
        <Text style={styles.ctaTitle}>Ready to meet your perfect fitness companion?</Text>
        <Text style={styles.ctaDescription}>
          Take our quick 3-minute survey to personalize your Gymmy experience
        </Text>

        <TouchableOpacity 
          style={styles.primaryButton}
          onPress={handleGetStarted}
          activeOpacity={0.8}
        >
          <Text style={styles.primaryButtonText}>Let&apos;s Get Started!</Text>
          <Ionicons name="arrow-forward" size={20} color="white" />
        </TouchableOpacity>

        <TouchableOpacity 
          style={styles.secondaryButton}
          onPress={handleSkipForNow}
          activeOpacity={0.8}
        >
          <Text style={styles.secondaryButtonText}>Skip for now</Text>
        </TouchableOpacity>
      </Animated.View>

      {/* Fun Facts */}
      <Animated.View 
        style={[
          styles.funFactsSection,
          {
            opacity: fadeAnim,
          },
        ]}
      >
        <Text style={styles.funFactText}>
          💡 Fun fact: Users who complete personalization are 3x more likely to stick with their fitness goals!
        </Text>
      </Animated.View>
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: '#f8f9fa',
  },
  topRightActions: {
    position: 'absolute',
    top: 14,
    right: 14,
    zIndex: 20,
  },
  gearButton: {
    paddingHorizontal: 10,
    paddingVertical: 8,
    borderRadius: 999,
    borderWidth: 1,
  },
  gearOn: {
    backgroundColor: '#ff6b35',
    borderColor: '#ff6b35',
  },
  gearOff: {
    backgroundColor: '#ffffff',
    borderColor: '#e5e7eb',
  },
  heroSection: {
    backgroundColor: '#007AFF',
    paddingTop: 60,
    paddingBottom: 40,
    paddingHorizontal: 24,
    alignItems: 'center',
    borderBottomLeftRadius: 30,
    borderBottomRightRadius: 30,
  },
  heroContent: {
    alignItems: 'center',
  },
  logoContainer: {
    marginBottom: 24,
  },
  logoCircle: {
    width: 100,
    height: 100,
    borderRadius: 50,
    backgroundColor: 'rgba(255,255,255,0.2)',
    alignItems: 'center',
    justifyContent: 'center',
    borderWidth: 3,
    borderColor: 'rgba(255,255,255,0.3)',
  },
  logoEmoji: {
    fontSize: 40,
  },
  welcomeTitle: {
    fontSize: 32,
    fontWeight: 'bold',
    color: 'white',
    marginBottom: 12,
    textAlign: 'center',
  },
  welcomeSubtitle: {
    fontSize: 18,
    color: 'rgba(255,255,255,0.9)',
    textAlign: 'center',
    lineHeight: 24,
    maxWidth: 280,
  },
  featuresSection: {
    paddingHorizontal: 24,
    paddingVertical: 32,
  },
  featuresTitle: {
    fontSize: 22,
    fontWeight: 'bold',
    color: '#212529',
    textAlign: 'center',
    marginBottom: 24,
  },
  featuresList: {
    gap: 20,
  },
  featureItem: {
    flexDirection: 'row',
    alignItems: 'center',
    backgroundColor: 'white',
    padding: 16,
    borderRadius: 12,
    shadowColor: '#000',
    shadowOffset: {
      width: 0,
      height: 1,
    },
    shadowOpacity: 0.05,
    shadowRadius: 3,
    elevation: 2,
  },
  featureIcon: {
    width: 48,
    height: 48,
    borderRadius: 24,
    backgroundColor: '#f8f9fa',
    alignItems: 'center',
    justifyContent: 'center',
    marginRight: 16,
  },
  featureContent: {
    flex: 1,
  },
  featureTitle: {
    fontSize: 16,
    fontWeight: '600',
    color: '#212529',
    marginBottom: 4,
  },
  featureDescription: {
    fontSize: 14,
    color: '#6c757d',
    lineHeight: 18,
  },
  ctaSection: {
    paddingHorizontal: 24,
    paddingVertical: 24,
    backgroundColor: 'white',
    marginHorizontal: 16,
    borderRadius: 16,
    shadowColor: '#000',
    shadowOffset: {
      width: 0,
      height: 2,
    },
    shadowOpacity: 0.1,
    shadowRadius: 8,
    elevation: 4,
  },
  ctaTitle: {
    fontSize: 20,
    fontWeight: 'bold',
    color: '#212529',
    textAlign: 'center',
    marginBottom: 12,
    lineHeight: 26,
  },
  ctaDescription: {
    fontSize: 16,
    color: '#6c757d',
    textAlign: 'center',
    marginBottom: 24,
    lineHeight: 22,
  },
  primaryButton: {
    backgroundColor: '#007AFF',
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'center',
